        username: val(f, r, "สร้างโดย") || val(f, r, "ดำเนินการโดย"),
        ref: val(f, r, "รหัสรายการ"),
        note: val(f, r, "หมายเหตุ"),
        ...noteHints(val(f, r, "หมายเหตุ")),
        raw: r.join(" | "),
