  const TITLE_RE = /^(คุณ|นางสาว|นาง|นาย|น\.ส\.|น\.ส|ที่)/;
  const BANK_KW = { scb:"SCB", kb:"KBANK", kbank:"KBANK", ktb:"KTB", bbl:"BBL", gsb:"GSB", tmn:"TMN", bay:"BAY", lbk:"LBK", krungsri:"BAY", ttb:"TTB", uob:"UOB" };
  const PM_KW = { atp:"AUTOPEER", autopeer:"AUTOPEER", az:"AZPAY", azpay:"AZPAY",
                  cby:"CYBERPLUS", cyber:"CYBERPLUS", cyberplus:"CYBERPLUS", cynerplus:"CYBERPLUS", "12pay":"12PAY", mypay:"MYPAY" };

  function normalizeAccount(s, bank) {
    let d = String(s || "").replace(/\D/g, "");
    if (bank === "TMN" && d.length === 9) d = "0" + d; // เบอร์ทรูมันนี่ตัด 0 หน้า
    return d;
  }
  // ตัดวรรณยุกต์/การันต์/ไม้ไต่คู้ (U+0E47–U+0E4E) ที่มักหายไปตอนตั้งชื่อไฟล์ เช่น "อภิเชษฐ์" vs "อภิเชษฐ"
  // คงสระไว้ (ต่ำกว่า 0E47) ชื่อจึงยังแยกจากกันได้
  const norm = (s) => String(s || "").toLowerCase().replace(/[็-๎]/g, "");
  function tokens(s){ return norm(s).replace(/[._/\\()-]/g," ").split(/\s+/).filter(Boolean); }
  function nameWords(name){
    return String(name||"").split(/\s+/).map((w)=>w.replace(TITLE_RE,"")).filter((w)=>w.length>=2);
  }
  function dirOf(fileName){
    const r = norm(fileName);
    const toks = tokens(fileName);
    const deposit = /ฝาก|deposit/.test(r) || toks.includes("d") || toks.includes("dw");
    const withdraw = /ถอน|withdraw/.test(r) || toks.includes("w") || toks.includes("dw");
    if (deposit && withdraw) return "both";
    if (deposit) return "deposit";
    if (withdraw) return "withdraw";
    return null;
  }
  // ตรวจ ธนาคาร/ผู้ให้บริการ จากชื่อไฟล์ (รองรับคำที่เขียนติดกัน)
  function detectFromName(fileName){
    const raw = norm(fileName), toks = tokens(fileName);
    let bank=null, pm=null;
    for (const t of toks){ if (BANK_KW[t]){ bank=BANK_KW[t]; break; } }
    for (const t of toks){ if (PM_KW[t]){ pm=PM_KW[t]; break; } }
    if (!pm){ for (const k in PM_KW){ if (k.length>=3 && raw.includes(k)){ pm=PM_KW[k]; break; } } }
    if (!bank){ for (const k in BANK_KW){ if (k.length>=3 && raw.includes(k)){ bank=BANK_KW[k]; break; } } }
    return { bank, pm, toks, raw };
  }

  /* คืนบัญชี/ช่องทางในทะเบียนที่ตรงกับชื่อไฟล์มากที่สุด */
  function matchFile(fileName){
    const { bank, pm, raw } = detectFromName(fileName);
    const direction = dirOf(fileName);
    if (pm){
      // ไฟล์ PM: ผู้ให้บริการ + บริษัทย่อยในชื่อไฟล์ (ยุบ ถอน/ฝาก เป็นบัญชีเดียว)
      const fileToks = tokens(fileName);
      // 1) จับชื่อบริษัทย่อยแบบเต็ม เช่น "sk8" (รวมกรณีเขียนติดกับคำอื่น)
      let hit = ACCOUNTS.filter((a)=>a.source==="pm" && a.provider===pm && norm(a.subco).length>=2 && raw.includes(norm(a.subco)));
      // 2) ถ้าไม่เจอ ลองตัวย่อ = ตัดเลขท้าย (sk8->sk, mr9->mr) แต่ต้องเป็น "คำเดี่ยว" ในชื่อไฟล์ และชี้ชัดบริษัทเดียว
      if (!hit.length){
        const shortHit = ACCOUNTS.filter((a)=>{
          if (a.source!=="pm" || a.provider!==pm) return false;
          const sh = norm(a.subco).replace(/\d+$/, "");
          return sh.length>=2 && fileToks.includes(sh);
        });
        if (new Set(shortHit.map((a)=>a.subco)).size === 1) hit = shortHit;
      }
      if (hit.length){
        const a=hit[0];
        return { match:{subco:a.subco,provider:a.provider,channel:a.channel,source:"pm",account:""}, direction, score:2 };
      }
      // เจอผู้ให้บริการแต่ไม่มีบริษัทย่อยในชื่อไฟล์ -> กำกวม
      const subs=[...new Set(ACCOUNTS.filter((a)=>a.source==="pm"&&a.provider===pm).map((a)=>a.subco))];
      return { match:null, provider:pm, direction, ambiguousSubco:subs, reason:"ไฟล์ PM ไม่มีชื่อบริษัทย่อยในชื่อไฟล์ (เพิ่มบริษัทย่อยในชื่อไฟล์)" };
    }
    if (bank){
      const scored = ACCOUNTS.filter((a)=>a.source==="bank" && a.bank===bank)
        .map((a)=>({a, score: nameWords(a.name).filter((w)=>raw.includes(norm(w))).length}))
        .filter((x)=>x.score>0)
        .sort((x,y)=>y.score-x.score);
      if (!scored.length) return { match:null, bank, direction, reason:"พบธนาคารแต่จับชื่อบัญชีไม่ได้" };
      const top=scored.filter((c)=>c.score===scored[0].score);
      const a=top[0].a;
      const res={ match:{subco:a.subco,provider:a.provider,bank:a.bank,account:a.account,name:a.name,source:"bank"}, direction, score:top[0].score };
      if (top.length>1) res.ambiguous=top.map((c)=>c.a.account);
      return res;
    }
    return { match:null, direction, reason:"ระบุธนาคาร/ผู้ให้บริการจากชื่อไฟล์ไม่ได้" };
  }

  function byAccount(accountDigits){
    const d=normalizeAccount(accountDigits);
    return ACCOUNTS.find((a)=>a.account && (a.account===d || normalizeAccount(a.account)===d)) || null;
  }
  return { ACCOUNTS, normalizeAccount, matchFile, byAccount, detectFromName, dirOf };
})();
if (typeof window !== "undefined") window.Registry = Registry;


/* =============================================================
   Engine - parser + bank rule engine + reconciliation
   Phase 1 ของ roadmap ทำงานจริงในเบราว์เซอร์
   - อ่าน CSV (และ XLSX ถ้ามี SheetJS)
   - ตรวจจับรูปแบบไฟล์และธนาคารจาก header
   - ใช้กฎธนาคารกรองบรรทัดขยะและตีความ direction
   - จับคู่ 3 จุด (account + time + amount) แบบคำนวณสด พร้อม progress
   ============================================================= */

const Engine = (() => {
  /* ---------------- CSV parser (รองรับ quote และ \r\n) ---------------- */
  function parseCSV(text) {
    if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
    const rows = [];
    let row = [];
    let field = "";
    let inQuote = false;
    for (let i = 0; i < text.length; i++) {
      const c = text[i];
      if (inQuote) {
        if (c === '"') {
          if (text[i + 1] === '"') {
            field += '"';
            i++;
          } else inQuote = false;
        } else field += c;
      } else if (c === '"') inQuote = true;
      else if (c === ",") {
        row.push(field);
        field = "";
      } else if (c === "\n") {
        row.push(field);
        field = "";
        rows.push(row);
        row = [];
      } else if (c !== "\r") field += c;
    }
    if (field.length || row.length) {
      row.push(field);
      rows.push(row);
    }
    return rows.filter((r) => r.some((c) => String(c).trim() !== ""));
  }

  /* อ่าน .xlsx — ใช้ตัวอ่านในตัว (XlsxReader) ทำงานได้แม้ออฟไลน์ */
  async function parseSheet(arrayBuffer) {
    if (typeof XlsxReader !== "undefined") return XlsxReader.read(arrayBuffer);
    if (typeof XLSX === "undefined") throw new Error("ยังโหลดตัวอ่านไฟล์ Excel ไม่ได้ — กรุณาใช้ไฟล์ .csv แทน");
    const wb = XLSX.read(arrayBuffer, { type: "array", cellDates: false, raw: false });
    const ws = wb.Sheets[wb.SheetNames[0]];
    return XLSX.utils.sheet_to_json(ws, { header: 1, blankrows: false, defval: "" }).map((r) => r.map((c) => String(c ?? "")));
  }

  /* ---------------- header mapping ---------------- */
  const DICT = {
    datetime: ["datetime", "วันที่เวลา", "วันเวลา", "date_time", "timestamp"],
    date: ["วันที่", "date", "วันที่ทำรายการ", "transaction date"],
    time: ["เวลา", "time"],
    desc: ["รายการ", "รายละเอียด", "หมายเหตุ", "description", "detail", "narrative", "merchant"],
    debit: ["ถอน", "ถอนเงิน", "โอนออก", "debit", "withdraw"],
    credit: ["ฝาก", "ฝากเงิน", "รับเข้า", "credit", "deposit"],
    balance: ["คงเหลือ", "ยอดคงเหลือ", "balance"],
    channel: ["ช่องทาง", "channel"],
    account: ["เลขที่บัญชี", "เลขบัญชีสมาชิก", "บัญชี", "ธนาคาร", "account", "account_no"],
    amount: ["จำนวนเงิน", "จำนวน", "ยอดเงิน", "amount", "ยอด"],
    username: ["username", "ยูสเซอร์", "ผู้ใช้", "user", "employee"],
    company: ["company", "บริษัท", "merchant"],
    status: ["status", "สถานะ"],
    bank: ["bank", "ธนาคาร"],
    txid: ["transaction_id", "txid", "ref", "รหัส", "เลขที่รายการ", "reference"],
    direction: ["direction", "ประเภทรายการ", "type"],
  };

  function mapHeaders(headerRow) {
    const map = {};
    if (!Array.isArray(headerRow)) return map;
    headerRow.forEach((raw, idx) => {
      const cell = String(raw).trim().toLowerCase();
      if (!cell) return;
      for (const [key, words] of Object.entries(DICT)) {
        if (map[key] !== undefined) continue;
        if (words.some((w) => cell === w.toLowerCase() || cell.includes(w.toLowerCase()))) {
          map[key] = idx;
          break;
        }
      }
    });
    return map;
  }

  /* ---------------- format detection ---------------- */
  const BANK_HINTS = [
    { code: "SCB", words: ["scb", "ไทยพาณิชย์"] },
    { code: "KBANK", words: ["kbank", "kasikorn", "กสิกร"] },
    { code: "GSB", words: ["gsb", "ออมสิน", "mymo"] },
    { code: "BBL", words: ["bbl", "bangkok bank", "กรุงเทพ"] },
    { code: "KTB", words: ["ktb", "krungthai", "กรุงไทย"] },
  ];

  function detectFormat(fileName, rows) {
    rows = Array.isArray(rows) ? rows.filter(Array.isArray) : [];
    const name = String(fileName || "").toLowerCase();
    const headerIdx = rows.findIndex((r) => mapHeaders(r).account !== undefined || mapHeaders(r).amount !== undefined || mapHeaders(r).balance !== undefined);
    const header = rows[headerIdx >= 0 ? headerIdx : 0] || [];
    const map = mapHeaders(header);
    const blob = (name + " " + rows.slice(0, 8).flat().join(" ")).toLowerCase();

    let source = "unknown";
    if (map.txid !== undefined && map.username !== undefined) source = "bo";
    else if (map.status !== undefined && map.amount !== undefined && map.username === undefined) source = "pm";
    else if (map.balance !== undefined || (map.debit !== undefined && map.credit !== undefined)) source = "stm";
    if (name.startsWith("pm_") || blob.includes("autopeer") || blob.includes("azpay") || blob.includes("cyberplus") || blob.includes("12pay") || blob.includes("mypay") || blob.includes(" atp ")) source = "pm";
    if (name.startsWith("bo_")) source = "bo";

    let bank = null;
    if (source !== "bo") for (const b of BANK_HINTS) if (b.words.some((w) => blob.includes(w))) bank = b.code;
    if (!bank && source !== "bo" && map.account !== undefined) {
      const sampleAcc = (rows[headerIdx + 2] || rows[headerIdx + 1] || [])[map.account] || "";
      const m = String(sampleAcc).split("-")[0].toUpperCase();
      if (BANK_HINTS.some((b) => b.code === m)) bank = m;
    }

    let company = null;
    ["AUTOPEER", "AZPAY", "COREPAY", "CPPAY", "CPXM", "CYBERPLUS", "12PAY", "MYPAY", "SYS123"].forEach((c) => {
      if (blob.toUpperCase().includes(c)) company = c;
    });

    return { source, bank, company, headerIdx: headerIdx >= 0 ? headerIdx : 0, map };
  }

  /* ---------------- helpers ---------------- */
  const numOf = (v) => {
    const n = parseFloat(String(v ?? "").replace(/[,\s฿]/g, ""));
    return Number.isFinite(n) ? n : null;
  };
  function secOf(dateStr, timeStr) {
    const t = String(timeStr || "").trim();
    const m = t.match(/(\d{1,2}):(\d{2})(?::(\d{2}))?/);
    if (!m) return null;
    return +m[1] * 3600 + +m[2] * 60 + (+m[3] || 0);
  }
  function isoDateOf(v) {
    const s = String(v || "").trim();
    let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (m) return `${m[1]}-${m[2]}-${m[3]}`;
    m = s.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})/);
    if (m) return `${m[3]}-${String(m[2]).padStart(2, "0")}-${String(m[1]).padStart(2, "0")}`;
    return null;
  }
  const pad = (n) => String(n).padStart(2, "0");
  const hhmmss = (sec) => `${pad(Math.floor(sec / 3600))}:${pad(Math.floor((sec % 3600) / 60))}:${pad(sec % 60)}`;

  /* ---------------- normalize + bank rules ---------------- */
  const CARRY_FORWARD = ["ยอดยกมา", "ยอดยกไป", "balance b/f", "brought forward"];
  const CYCLE_LINE = ["รอบวันที่", "statement period", "รอบบัญชี"];

  function normalize(fileName, rows, settings, businessDate) {
    /* 1) ลองรูปแบบรายงานจริงของแผนกก่อน (AT4 / FR8 / บริษัทอื่นใช้ร่วมกัน) */
    if (typeof Formats !== "undefined") {
      const real = Formats.parse(fileName, rows, businessDate);
      if (real) {
        const pmOnly = Object.entries(real.channels).filter(([, c]) => c.isPm);
        const warnings = real.warnings.slice();
        if (pmOnly.length) {
          warnings.push("ช่องทาง PM ที่พบ: " + pmOnly.map(([k, c]) => `${k} ${c.count} รายการ`).join(", ") + " — ต้องมีไฟล์ statement ของช่องทางนี้จึงจะจับคู่ได้");
        }
        return {
          fileName,
          format: {
            // ใช้ side ที่ตัวอ่านรูปแบบจริงระบุ: PM provider เป็น STM, รายงานหลังบ้านเป็น BO
            source: real.side === "aux" ? "aux" : real.side === "stm" ? "stm" : "bo",
            bank: null,
            company: real.company,
            headerIdx: 0,
            map: {},
            realCode: real.code,
            realLabel: real.label,
            channels: real.channels,
          },
          records: real.records,
          aux: real.aux,
          dropped: real.dropped,
          warnings,
        };
      }
    }

    const fmt = detectFormat(fileName, rows);
    const map = fmt.map;
    const records = [];
    const dropped = {};
    const warnings = [];
    const drop = (reason) => (dropped[reason] = (dropped[reason] || 0) + 1);

    for (let i = fmt.headerIdx + 1; i < rows.length; i++) {
      const r = rows[i];
      const joined = r.join(" ").toLowerCase();
      const desc = String(r[map.desc] ?? "").trim();

      if (settings.rules.filterCarryForward && CARRY_FORWARD.some((w) => joined.includes(w.toLowerCase()))) {
        drop("กรองบรรทัดยอดยกมา");
        continue;
      }
      if (settings.rules.filterCarryForward && CYCLE_LINE.some((w) => joined.includes(w.toLowerCase()))) {
        drop("กรองบรรทัดรอบวันที่");
        continue;
      }

      // วันที่และเวลา
      const dateVal = map.datetime !== undefined ? r[map.datetime] : r[map.date];
      const timeVal = map.time !== undefined ? r[map.time] : dateVal;
      const iso = isoDateOf(dateVal);
      const sec = secOf(iso, timeVal);
      if (sec === null) {
        drop("ไม่มีเวลาที่อ่านได้");
        continue;
      }
      if (businessDate && iso && iso !== businessDate) {
        drop("วันที่ไม่ตรงกับวันที่ตรวจ");
        continue;
      }

      // ยอดและทิศทาง
      let amount = null;
      let direction = null;
      if (map.debit !== undefined || map.credit !== undefined) {
        const dr = numOf(r[map.debit]);
        const cr = numOf(r[map.credit]);
        if (cr) {
          amount = cr;
          direction = "deposit";
        } else if (dr) {
          amount = dr;
          direction = "withdraw";
        }
      }
      if (amount === null && map.amount !== undefined) amount = numOf(r[map.amount]);
      if (amount === null || amount === 0) {
        drop("ไม่มียอดเงิน");
        continue;
      }

      // กฎรายธนาคาร: ตีความ direction จาก marker (ใช้เฉพาะฝั่งธนาคาร)
      const account0 = String(r[map.account] ?? "").trim();
      const rowBank = map.bank !== undefined ? String(r[map.bank] ?? "").trim().toUpperCase() : "";
      const bank = fmt.source === "bo" ? rowBank || account0.split("-")[0].toUpperCase() : fmt.bank || rowBank || account0.split("-")[0].toUpperCase();
      let adjustment = false;
      if (fmt.source !== "bo" && bank === "SCB") {
        const marker = desc.toUpperCase();
        if (marker.includes("X1")) direction = "deposit";
        else if (marker.includes("X2")) direction = "withdraw";
        else if (marker.includes("XB")) {
          adjustment = true;
          direction = "adjustment";
        }
      } else if (fmt.source !== "bo" && bank === "GSB") {
        const d = desc.toLowerCase();
        if (d.includes("transfer sav deposit") || d.includes("transfer from sav")) direction = "deposit";
        else if (d.includes("sav withdraw")) direction = "withdraw";
      }
      if (adjustment) {
        drop("รายการปรับปรุงยอด (XB) แยกออกจากการจับคู่");
        continue;
      }

      // PM: เฉพาะรายการสำเร็จ
      if (map.status !== undefined) {
        const st = String(r[map.status]).trim().toUpperCase();
        if (settings.rules.pmSuccessOnly && st && st !== "SUCCESS" && st !== "สำเร็จ") {
          drop("รายการไม่สำเร็จ (PM)");
          continue;
        }
      }

      if (map.direction !== undefined) {
        const d = String(r[map.direction]).toUpperCase();
        if (d.includes("DEPOSIT") || d.includes("ฝาก")) direction = "deposit";
        else if (d.includes("WITHDRAW") || d.includes("ถอน")) direction = "withdraw";
      }

      const account = account0 || "UNKNOWN";
      records.push({
        rowNo: i + 1,
        sec,
        date: iso || businessDate,
        amount: Math.round(amount * 100) / 100,
        direction: direction || "deposit",
        account,
        bank: bank || account.split("-")[0].toUpperCase(),
        company: fmt.company || String(r[map.company] ?? "").trim() || null,
        username: String(r[map.username] ?? "").trim() || null,
        ref: String(r[map.txid] ?? "").trim() || null,
        desc,
        crossDay: sec >= 82800,
        raw: r.join(" | "),
      });
    }

    if (!records.length) warnings.push("อ่านไฟล์ได้แต่ไม่พบรายการที่ใช้จับคู่ได้ — ตรวจหัวคอลัมน์อีกครั้ง");
    if (fmt.source === "unknown") warnings.push("ระบุไม่ได้ว่าเป็น STM, BO หรือ PM — ระบบจะถือว่าเป็น STM");
    return { fileName, format: fmt, records, dropped, warnings };
  }

  /* ---------------- reconciliation ---------------- */
  const TYPE_NAME = {
    time_diff: "เวลาเกิน tolerance",
    missing_bo: "STM มากกว่า BO",
    missing_stm: "BO มากกว่า STM",
    amount_diff: "ยอดเงินไม่ตรง",
    cross_day: "รายการข้ามวัน (BO กับธนาคารคนละวัน)",
    duplicate: "เติมซ้ำ / รายการซ้ำ",
    wrong_bank: "เลือกธนาคารผิด",
    wrong_account: "ลูกค้าฝากผิดบัญชี",
  };
  const BASE_SEVERITY = {
    time_diff: "low",
    missing_bo: "high",
    missing_stm: "high",
    amount_diff: "critical",
    cross_day: "medium",
    duplicate: "critical",
    wrong_bank: "medium",
    wrong_account: "medium",
  };
  const SLA_OF = { critical: 4, high: 8, medium: 48, low: 72 };
  const shiftOf = (h) => (h >= 8 && h < 16 ? "morning" : h >= 16 ? "afternoon" : "night");
  const key2 = (a, amt) => a + "|" + amt.toFixed(2);
  const isIsoDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v || ""));
  const canonicalDirection = (v) => (/ถอน|withdraw/i.test(String(v || "")) ? "withdraw" : /ฝาก|deposit/i.test(String(v || "")) ? "deposit" : String(v || ""));
  const recordKey = (r) =>
    [r.account || "-", Number(r.amount || 0).toFixed(2), r.date || "", Number.isFinite(Number(r.sec)) ? Number(r.sec) : "", canonicalDirection(r.direction)].join("|");
  /* เทียบ timestamp จริงเมื่อมีวันที่ทั้งสองฝั่ง เพื่อรองรับ 23:59 -> 00:01
     ถ้าวันที่ขาด ใช้เวลาในวันแทน และปล่อย quality gate เป็นผู้แจ้งปัญหาวันที่ */
  const timeDistance = (a, b) => {
    if (!a || !b) return Infinity;
    const aSec = Number(a.sec);
    const bSec = Number(b.sec);
    if (!Number.isFinite(aSec) || !Number.isFinite(bSec)) return Infinity;
    if (isIsoDate(a.date) && isIsoDate(b.date)) {
      const aDay = Date.parse(a.date + "T00:00:00Z");
      const bDay = Date.parse(b.date + "T00:00:00Z");
      if (Number.isFinite(aDay) && Number.isFinite(bDay)) return Math.abs(aDay / 1000 + aSec - (bDay / 1000 + bSec));
    }
    return Math.abs(aSec - bSec);
  };

  function chunked(items, size, worker, onProgress, label) {
    return new Promise((resolve) => {
      let i = 0;
      function step() {
        const end = Math.min(i + size, items.length);
        for (; i < end; i++) worker(items[i], i);
        if (onProgress) onProgress(i / (items.length || 1), label);
        if (i < items.length) setTimeout(step, 0);
        else resolve();
      }
      step();
    });
  }

  async function reconcile(stmRecords, boRecords, settings, masterAccounts, onProgress) {
    const t0 = performance.now();
    const tolDep = settings.toleranceDeposit;
    const tolWit = settings.toleranceWithdraw;
    /* กรอบผ่อนปรนสำหรับคู่ exact ที่ไม่กำกวม: ใช้เมื่อ account/provider + ยอด +
       ทิศทางตรง และทั้งสองฝั่งมีผู้สมัครเพียงคู่เดียวเท่านั้น เพื่อไม่ให้ยอดกลม ๆ
       ที่เกิดซ้ำ (100/500/1,000) ถูกจับผิดรายการ */
    const exactUniqueTol = Math.max(tolDep, tolWit, Number(settings.exactUniqueTolerance || 0));
    /* อายุเคสสำหรับ SLA: ถ้าผู้เรียกส่ง settings.asOf (เวลาจริง เป็น epoch ms) มา จะคิดอายุจากเวลาที่ผ่านจริง
       ถ้าไม่ส่งมา จะ fallback เป็นสูตรเดิม (สมมติ "ตอนนี้" = ปลายวันที่ตรวจ) เพื่อความเข้ากันได้กับข้อมูลย้อนหลัง/ตัวอย่าง */
    const asOf = settings && settings.asOf ? Number(settings.asOf) : null;
    const ageHoursOf = (src) => {
      if (asOf && src && src.date) {
        const base = Date.parse(src.date + "T00:00:00");
        if (Number.isFinite(base)) return Math.max(1, Math.floor((asOf - (base + src.sec * 1000)) / 3600000));
      }
      return 1 + Math.floor((86400 - src.sec) / 3600);
    };
    /* statement ของ KBANK/SCB ให้เวลาแค่ HH:MM — ต้องเผื่ออย่างน้อย 1 นาที */
    const minuteFloor = settings.minuteTolerance ?? 60;
    const tolOf = (d, s, b) => {
      // สเตทเมนต์ไม่มีเวลา (เช่น BBL): จับคู่ด้วยบัญชี+ยอด+ทิศทางภายในวัน (กรอบเวลาทั้งวัน)
      if ((s && s.noTime) || (b && b.noTime)) return 86400;
      const base = d === "withdraw" ? tolWit : tolDep;
      const coarse = (s && s.minutePrecision) || (b && b.minutePrecision);
      return coarse ? Math.max(base, minuteFloor) : base;
    };
    const masterSet = new Set((masterAccounts || []).map((a) => a.id));

    /* บัญชี/ช่องทางที่มีไฟล์ฝั่ง statement จริง — ที่ไม่มีจะไม่ถูกนับเป็น exception */
    const stmAccounts = new Set(stmRecords.map((r) => r.account));
    const stmChannels = new Set(stmRecords.map((r) => (r.channel || r.bank || "").toUpperCase()).filter(Boolean));
    const hasStmSide = (b) => stmAccounts.has(b.account) || (b.channel && stmChannels.has(String(b.channel).toUpperCase()));
    const noStmSide = [];

    // index BO
    const exactIdx = new Map();
    const accIdx = new Map();
    const boUsed = new Uint8Array(boRecords.length);
    await chunked(
      boRecords,
      20000,
      (b, i) => {
        const k = key2(b.account, b.amount);
        let arr = exactIdx.get(k);
        if (!arr) exactIdx.set(k, (arr = []));
        arr.push(i);
        let arr2 = accIdx.get(b.account);
        if (!arr2) accIdx.set(b.account, (arr2 = []));
        arr2.push(i);
      },
      onProgress,
      "สร้างดัชนีฝั่ง BO",
    );

    const matched = [];
    const exceptions = [];
    const stmLeft = [];
    let timeDiffCount = 0;

    /* ทิศทางต้องตรงกัน (ฝากจับคู่ฝาก / ถอนจับคู่ถอน) — ถ้าฝั่งใดไม่มี direction ให้ผ่าน (กันรายการที่ระบุทิศไม่ได้) */
    const dirOK = (s, b) => !s.direction || !b.direction || s.direction === b.direction;

    // pass 1a: จับคู่ exact (บัญชี+ยอด+ทิศทาง) ที่อยู่ "ในเกณฑ์เวลา" ให้ครบก่อน
    //   ทำก่อนขั้น time_diff เพื่อกันรายการที่เวลาใกล้กว่าถูกแย่ง BO ไปโดยรายการที่อยู่ไกลกว่า
    const stmMid = [];
    await chunked(
      stmRecords,
      10000,
      (s) => {
        const cands = exactIdx.get(key2(s.account, s.amount));
        let best = -1;
        let bestDt = Infinity;
        if (cands) {
          for (const ci of cands) {
            if (boUsed[ci]) continue;
            const b = boRecords[ci];
            if (!dirOK(s, b)) continue;
            const dt = timeDistance(b, s);
            if (dt <= tolOf(s.direction, s, b) && dt < bestDt) {
              bestDt = dt;
              best = ci;
            }
          }
        }
        if (best >= 0) {
          boUsed[best] = 1;
          matched.push({ s, b: boRecords[best], dt: bestDt });
          if (bestDt > tolOf(s.direction, s, boRecords[best]) * 0.6) timeDiffCount++;
        } else {
          stmMid.push(s);
        }
      },
      onProgress,
      "จับคู่ 3 จุด (ในเกณฑ์)",
    );

    // pass 1b: ผ่อนเวลาให้คู่ exact ที่มีเพียงคู่เดียว (ค่าใช้งานจริง 10 นาที)
    const stmFar = [];
    const pendingByKey = new Map();
    stmMid.forEach((s) => {
      const k = key2(s.account, s.amount) + "|" + (s.direction || "");
      let arr = pendingByKey.get(k);
      if (!arr) pendingByKey.set(k, (arr = []));
      arr.push(s);
    });
    const extendedMatched = new Set();
    await chunked(
      stmMid,
      10000,
      (s) => {
        const cands = exactIdx.get(key2(s.account, s.amount)) || [];
        const eligible = cands.filter((ci) => {
          if (boUsed[ci]) return false;
          const b = boRecords[ci];
          return dirOK(s, b) && timeDistance(b, s) <= exactUniqueTol;
        });
        if (exactUniqueTol > tolOf(s.direction, s, null) && eligible.length === 1) {
          const ci = eligible[0];
          const b = boRecords[ci];
          const key = key2(s.account, s.amount) + "|" + (s.direction || "");
          const competingStm = (pendingByKey.get(key) || []).some((other) =>
            other !== s && !extendedMatched.has(other) && timeDistance(other, b) <= exactUniqueTol,
          );
          if (!competingStm) {
            boUsed[ci] = 1;
            extendedMatched.add(s);
            matched.push({ s, b, dt: timeDistance(b, s), extendedTimeMatch: true });
            return;
          }
        }
        stmFar.push(s);
      },
      onProgress,
      "จับคู่ยอดตรงที่ไม่กำกวม",
    );

    // pass 1c: รายการที่ยังไม่แม็ป — หา BO บัญชี+ยอด+ทิศทางเดียวกันที่ใกล้สุด (นอกเกณฑ์แต่ <1 ชม.) = ต่างเวลา
    await chunked(
      stmFar,
      10000,
      (s) => {
        const cands = exactIdx.get(key2(s.account, s.amount));
        let best = -1;
        let bestDt = Infinity;
        if (cands) {
          for (const ci of cands) {
            if (boUsed[ci]) continue;
            const b = boRecords[ci];
            if (!dirOK(s, b)) continue;
            const dt = timeDistance(b, s);
            if (dt < bestDt) {
              bestDt = dt;
              best = ci;
            }
          }
        }
        if (best >= 0 && bestDt < 3600) {
          boUsed[best] = 1;
          exceptions.push(mkException("time_diff", s, boRecords[best], bestDt));
        } else {
          stmLeft.push(s);
        }
      },
      onProgress,
      "จับคู่ 3 จุด (ต่างเวลา)",
    );

    // pass 2: ยอดไม่ตรง (บัญชีเดียวกัน เวลาใกล้กัน แต่ยอดต่าง)
    const stmLeft2 = [];
    await chunked(
      stmLeft,
      10000,
      (s) => {
        const cands = accIdx.get(s.account);
        let best = -1;
        let bestDt = Infinity;
        if (cands) {
          for (const ci of cands) {
            if (boUsed[ci]) continue;
            const b = boRecords[ci];
            if (!dirOK(s, b)) continue;
            const dt = timeDistance(b, s);
            if (dt < bestDt) {
              bestDt = dt;
              best = ci;
            }
          }
        }
        if (best >= 0 && bestDt <= tolOf(s.direction, s, boRecords[best])) {
          boUsed[best] = 1;
          exceptions.push(mkException("amount_diff", s, boRecords[best], bestDt));
        } else {
          stmLeft2.push(s);
        }
      },
      onProgress,
      "ตรวจยอดไม่ตรง",
    );

    // pass 3: STM ที่เหลือ = ไม่มีฝั่ง BO
    stmLeft2.forEach((s) => exceptions.push(mkException(s.crossDay ? "cross_day" : "missing_bo", s, null, 0)));

    // pass 4: BO ที่เหลือ = ไม่มีฝั่ง STM หรือเป็นรายการซ้ำ
    /* "ซ้ำ" = มีคู่ที่แม็ปไปแล้ว บัญชี+ยอด+ทิศทางเดียวกัน และเวลาใกล้กัน (ในเกณฑ์ tolerance)
       ถ้ายอดเท่ากันแต่คนละเวลา ถือเป็นคนละรายการ = missing_stm ไม่ใช่ duplicate */
    const dupKey = (a, amt, dir) => a + "|" + amt.toFixed(2) + "|" + (dir || "");
    const matchedTimes = new Map();
    matched.forEach((m) => {
      const k = dupKey(m.b.account, m.b.amount, m.b.direction);
      let arr = matchedTimes.get(k);
      if (!arr) matchedTimes.set(k, (arr = []));
      arr.push(m.b.sec);
    });
    await chunked(
      boRecords,
      20000,
      (b, i) => {
        if (boUsed[i]) return;
        if (!hasStmSide(b)) {
          noStmSide.push(b);
          return;
        }
        const times = matchedTimes.get(dupKey(b.account, b.amount, b.direction));
        const dupWin = Math.max(tolOf(b.direction, b, b), 120);
        const dup = times && times.some((t) => Math.abs(t - b.sec) <= dupWin);
        /* รายการ 23:00-23:59 หรือข้ามวัน ให้ถือเป็น cross_day ก่อน แม้ยอดจะซ้ำกับรายการอื่น */
        exceptions.push(mkException(b.lateNight || b.crossDay ? "cross_day" : dup ? "duplicate" : "missing_stm", null, b, 0));
      },
      onProgress,
      "ตรวจรายการที่ไม่มีฝั่ง STM",
    );

    // pass 5: กฎเพิ่มเติมบนคู่ที่จับได้ — เทียบกับ master list ของบัญชี ไม่ใช่ธนาคารที่เดาจากชื่อไฟล์
    const masterBank = new Map((masterAccounts || []).map((a) => [a.id, a.bank]));
    /* ข้อความในสลิปธนาคาร: 'จาก GSB X3463 ...' / 'รับโอนจาก KBANK x4845 ...' */
    const FROM_RE = /(?:จาก|ไป|from|to)\s*([A-Z]{2,6})?\s*[xX](\d{3,4})/;
    const BANK_ALIAS = { KBANK: "KBANK", KPLUS: "KBANK", SCB: "SCB", GSB: "GSB", BBL: "BBL", KTB: "KTB", BAAC: "BAAC", TTB: "TTB", BAY: "BAY", KK: "KKP", KKP: "KKP", UOB: "UOB", CIMB: "CIMB", LHB: "LHB", TISCO: "TISCO", GHB: "GHB" };
    matched.forEach((m) => {
      const truth = masterBank.get(m.s.account);
      /* ไฟล์ PM ใช้ชื่อ provider (เช่น AUTOPEER/CYBERPLUS) เป็น match key ไม่ใช่
         เลขบัญชีธนาคารบริษัท จึงห้ามนำ provider ไปเทียบกับ master account list
         มิฉะนั้นคู่ที่ยอด/เวลา/ช่องทางตรงกันจะถูกสร้าง wrong_account เท็จเกือบทั้งหมด */
      if (masterSet.size && !truth && !m.s.isPmChannel) {
        exceptions.push(mkException("wrong_account", m.s, m.b, m.dt));
        return;
      }
      /* จุดตรวจที่ 4: ธนาคารและเลขบัญชีปลายทางของลูกค้าต้องตรงกับที่สลิปธนาคารระบุ */
      const hit = String(m.s.desc || m.s.raw || "").match(FROM_RE);
      if (!hit) return;
      const stmBank = BANK_ALIAS[(hit[1] || "").toUpperCase()] || (hit[1] || "").toUpperCase();
      const stmTail = hit[2];
      const boBank = BANK_ALIAS[String(m.b.custBank || "").toUpperCase()] || String(m.b.custBank || "").toUpperCase();
      const boTail = String(m.b.custAccount || "").replace(/\D/g, "").slice(-stmTail.length);
      if (boBank && stmBank && boBank !== stmBank) exceptions.push(mkException("wrong_bank", m.s, m.b, m.dt));
      else if (boTail && stmTail && boTail !== stmTail) exceptions.push(mkException("wrong_account", m.s, m.b, m.dt));
    });

    // สถิติรายชั่วโมงเพื่อให้ dashboard ตรงกับผลจับคู่จริง
    const hourlyStm = new Array(24).fill(0);
    const hourlyMatched = new Array(24).fill(0);
    let crossDayWindow = 0;
    stmRecords.forEach((r) => {
      hourlyStm[Math.floor(r.sec / 3600)]++;
      if (r.crossDay) crossDayWindow++;
    });
    matched.forEach((m) => hourlyMatched[Math.floor(m.s.sec / 3600)]++);

    // จัดรหัสและ metadata
    exceptions.sort((a, b) => a.sortSec - b.sortSec);
    exceptions.forEach((e, i) => (e.id = "EX-" + String(3001 + i)));

    const elapsed = Math.round(performance.now() - t0);
    return {
      matched: matched.length,
      exceptions,
      stmCount: stmRecords.length,
      boCount: boRecords.length,
      elapsedMs: elapsed,
      matchRate: stmRecords.length ? (matched.length / stmRecords.length) * 100 : 0,
      nearTolerance: timeDiffCount,
      hourlyStm,
      hourlyMatched,
      crossDayWindow,
      noStmSide: summarizeNoStm(noStmSide),
      noStmCount: noStmSide.length,
      /* ใช้เฉพาะใน Worker เพื่อไม่ให้ Rules เปิด cross_day ซ้ำกับคู่ที่ Engine จับสำเร็จ */
      matchedBoKeys: matched.map((m) => recordKey(m.b)),
    };

    function summarizeNoStm(list) {
      const by = {};
      list.forEach((b) => {
        const k = (b.channel || b.bank || b.account || "ไม่ระบุ") + " / " + (b.company || "-");
        const g = by[k] || (by[k] = { key: k, channel: b.channel || b.bank || "-", company: b.company || "-", count: 0, amount: 0, accounts: new Set() });
        g.count++;
        g.amount += b.amount;
        g.accounts.add(b.account);
      });
      return Object.values(by)
        .map((g) => ({ ...g, amount: Math.round(g.amount * 100) / 100, accounts: [...g.accounts] }))
        .sort((a, b) => b.count - a.count);
    }

    function mkException(type, s, b, dt) {
      const src = s || b;
      const sec = src.sec;
      const hour = Math.floor(sec / 3600);
      const severityBase = BASE_SEVERITY[type];
      const sysAmount = b ? b.amount : null;
      const bankAmount = s ? s.amount : null;
      const riskAmount = type === "time_diff" || type === "cross_day" ? 0 : type === "amount_diff" ? Math.abs(sysAmount - bankAmount) : src.amount;
      let severity = severityBase;
      if (severity !== "critical" && riskAmount > 10000) severity = "critical";
      const slaHours = SLA_OF[severity];
      const ageHours = ageHoursOf(src);
      return {
        sortSec: sec,
        date: src.date,
        time: hhmmss(sec),
        hour,
        /* ใช้บริษัทย่อย (subco) จากทะเบียนก่อน — company ของ statement ธนาคารเป็นรหัสธนาคาร (SCB/TMN/BAY) ไม่ใช่บริษัท */
        company: src.subco || src.company || (b && (b.subco || b.company)) || "SYS123",
        bank: src.bank,
        account: src.account,
        direction: src.direction === "withdraw" ? "ถอน" : src.direction === "deposit" ? "ฝาก" : "PM",
        systemAmount: sysAmount,
        bankAmount,
        amountDiff: sysAmount === null || bankAmount === null ? 0 : sysAmount - bankAmount,
        riskAmount,
        timeDiffSec: Math.round(dt),
        type,
        typeName: TYPE_NAME[type],
        severity,
        status: "open",
        shift: shiftOf(hour),
        employee: (b && b.username) || (s && s.username) || "ไม่ระบุ",
        assignee: "audit_som",
        track: null, // แอปจะเติมให้จากระบบต้นทางของบริษัท (XB = รายวัน, 123 = รายรอบ)
        cause: causeOf(type),
        ageHours,
        slaHours,
        overSla: ageHours > slaHours,
        hasEvidence: false,
        stmRaw: s ? s.raw : "— ไม่พบรายการฝั่ง STM ในช่วงเวลาที่ตรวจ —",
        boRaw: b ? b.raw : "— ไม่พบรายการฝั่ง BO ในช่วงเวลาที่ตรวจ —",
        boTime: b ? hhmmss(b.sec) : "-",
        notes: [],
        evidence: [],
        fromImport: true,
      };
    }
  }

  function causeOf(type) {
    return (
      {
        amount_diff: "คีย์ยอดผิดจากต้นฉบับ",
        missing_bo: "รายการฝั่งระบบหลังบ้านหายไป",
        missing_stm: "auto ไม่เข้า แล้วทำ manual ซ้ำ",
        time_diff: "เวลาระหว่างธนาคารกับระบบต่างกันเกินเกณฑ์",
        cross_day: "รายการค้างข้ามวันจากธนาคาร",
        duplicate: "ทำรายการซ้ำในระบบหลังบ้าน",
        wrong_bank: "เลือกธนาคารผิดตอนกดอนุมัติ",
        wrong_account: "ลูกค้าโอนเข้าบัญชีที่เลิกใช้",
      }[type] || "รอระบุสาเหตุ"
    );
  }

  return { parseCSV, parseSheet, detectFormat, normalize, reconcile, TYPE_NAME, hhmmss };
})();


/* =============================================================
   PdfStm - อ่าน statement ธนาคารที่เป็นไฟล์ PDF (ข้อความจริง ไม่ใช่ภาพสแกน)
   รองรับรูปแบบที่แผนกใช้จริง
     KBANK : 19-07-26 | 00:00 | รับโอนเงิน | 100.00 | 1,035.25 | K PLUS | จาก ...
     SCB   : 18/07/26 07:04 | X2 | ENET | 5,000.00 | 23,932.00   (+ บรรทัดรายละเอียดด้านบน)
   ใช้ pdf.js ที่ฝังมากับระบบ (vendor/) จึงทำงานได้แม้ไม่มีอินเทอร์เน็ต
   ============================================================= */

const PdfStm = (() => {
  const LIB = "vendor/pdf.min.js";
  const WORKER = "vendor/pdf.worker.min.js";
  let loading = null;

  function loadLib() {
    if (typeof pdfjsLib !== "undefined") return Promise.resolve(pdfjsLib);
    if (loading) return loading;
    loading = new Promise((resolve, reject) => {
      const s = document.createElement("script");
      s.src = LIB;
      s.onload = () => {
        if (typeof pdfjsLib === "undefined") return reject(new Error("โหลดตัวอ่าน PDF ไม่สำเร็จ"));
        pdfjsLib.GlobalWorkerOptions.workerSrc = WORKER;
        resolve(pdfjsLib);
      };
      s.onerror = () => reject(new Error("ไม่พบไฟล์ตัวอ่าน PDF (vendor/pdf.min.js)"));
      document.head.appendChild(s);
    });
    return loading;
  }

  /* ---------------- ดึงข้อความเป็นบรรทัด พร้อมตำแหน่ง x ---------------- */
  async function textLines(arrayBuffer) {
    const lib = await loadLib();
    const doc = await lib.getDocument({ data: new Uint8Array(arrayBuffer) }).promise;
    const pages = [];
    for (let pn = 1; pn <= doc.numPages; pn++) {
      const page = await doc.getPage(pn);
      const tc = await page.getTextContent();
      const buckets = new Map();
      tc.items.forEach((it) => {
        const y = Math.round(it.transform[5]);
        let hit = null;
        for (const key of buckets.keys()) if (Math.abs(key - y) <= 2) hit = key;
        const k = hit === null ? y : hit;
        if (!buckets.has(k)) buckets.set(k, []);
        buckets.get(k).push({ x: Math.round(it.transform[4]), s: it.str });
      });
      const lines = [...buckets.entries()]
        .sort((a, b) => b[0] - a[0])
        .map(([y, items]) => {
          const sorted = items.sort((a, b) => a.x - b.x);
          return { y, items: sorted, text: sorted.map((i) => i.s).join(" ").replace(/\s+/g, " ").trim() };
        });
      pages.push(lines);
    }
    return pages;
  }

  /* ---------------- helper ---------------- */
  const digits = (s) => String(s || "").replace(/\D/g, "");
  const numOf = (s) => {
    const n = parseFloat(String(s || "").replace(/[,\s]/g, ""));
    return Number.isFinite(n) ? n : null;
  };
  const AMT = /^-?[\d,]+\.\d{2}$/;

  /* '19-07-26' / '18/07/26' / '19/07/2026' -> ISO (รองรับ พ.ศ. 2 หลัก) */
  function isoOf(v) {
    const m = String(v || "").match(/(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})/);
    if (!m) return null;
    let y = +m[3];
    if (y < 100) y += y > 50 ? 1957 : 2000; // ค.ศ.ย่อ 26->2026 ; พ.ศ.ย่อ (KTB) 69->2026 (2569-543=1957+69)
    if (y > 2400) y -= 543;
    return `${y}-${String(m[2]).padStart(2, "0")}-${String(m[1]).padStart(2, "0")}`;
  }
  const secOf = (v) => {
    const m = String(v || "").match(/(\d{1,2}):(\d{2})(?::(\d{2}))?/);
    return m ? +m[1] * 3600 + +m[2] * 60 + (+m[3] || 0) : null;
  };

  /* ---------------- ตรวจธนาคารและเลขบัญชี ---------------- */
  function header(pages) {
    const blob = (pages[0] || []).map((l) => l.text).join("\n");
    const bodyBlob = (pages || []).map((p) => p.map((l) => l.text).join("\n")).join("\n");
    let bank = null;
    if (/ไทยพาณิชย์|SIAM COMMERCIAL/i.test(blob)) bank = "SCB";
    // LINE BK (LBK): สเตทเมนต์ฟอร์แมตเดียวกับกสิกร (เคลียริงเดียวกัน) แต่ต้องแท็กเป็น LBK ให้ตรงทะเบียนบัญชี — ตรวจก่อน KBANK เพราะมี "เลขที่บัญชีเงินฝาก" เหมือนกัน
    else if (/LINE\s*BK|ไลน์\s*บีเค/i.test(bodyBlob)) bank = "LBK";
    else if (/กสิกร|KASIKORN|K PLUS|เลขที่บัญชีเงินฝาก/i.test(blob)) bank = "KBANK";
    else if (/ออมสิน|MyMo|GSB/i.test(blob)) bank = "GSB";
    else if (/ธนาคารกรุงเทพ|BANGKOK BANK/i.test(blob)) bank = "BBL"; // ต้องมีคำว่า "ธนาคาร" นำ กัน "กรุงเทพฯ" ในที่อยู่สำนักงานใหญ่ธนาคารอื่น
    else if (/กรุงไทย|KRUNGTHAI/i.test(blob)) bank = "KTB";
    else if (/กรุงศรี|อยุธยา|KRUNGSRI|AYUDHYA/i.test(blob)) bank = "BAY";
    /* TrueMoney Wallet: หัวข้อ "ใบแสดงรายการ / Statement of Account" + คอลัมน์ เงินเข้า/เงินออก + ยอดคงเหลือ (เลขบัญชี = เบอร์มือถือ) */
    else if (/เงินเข้า/.test(blob) && /เงินออก/.test(blob) && /ยอดคงเหลือ/.test(blob)) bank = "TMN";

    let account = "";
    const am = blob.match(/(?:เลข(?:ที่)?บัญชี(?:เงินฝาก)?|Account No\.?)\s*[:\s]*([\d-]{9,20})/i) || blob.match(/\b(\d{3}-\d{1,6}-\d{1,2})\b/);
    if (am) account = digits(am[1]);

    let holder = "";
    const hm = blob.match(/ชื่อ\s*-?\s*สกุล\s*([^\n]{3,60})/) || blob.match(/ชื่อบัญชี\s*([^\n]{2,40}?)\s*เลขที่บัญชี/) || blob.match(/ชื่อบัญชี\s*([^\n]{3,60})/);
    if (hm) holder = hm[1].trim();

    let period = "";
    const pm = blob.match(/(\d{1,2}\/\d{1,2}\/\d{2,4})\s*-\s*(\d{1,2}\/\d{1,2}\/\d{2,4})/);
    if (pm) period = `${isoOf(pm[1])} ถึง ${isoOf(pm[2])}`;

    return { bank, account, holder, period };
  }

  /* ---------------- SCB ----------------
     บรรทัดรายการ: 18/07/26 07:04 | X2 | ENET | 5,000.00 | 23,932.00
     คำอธิบายอยู่บรรทัดเหนือขึ้นไปหนึ่งบรรทัด                                */
  function parseScb(pages) {
    const rows = [];
    pages.forEach((lines) => {
      lines.forEach((l, i) => {
        const t = l.text;
        const m = t.match(/^(\d{1,2}\/\d{1,2}\/\d{2,4})\s+(\d{1,2}:\d{2})\s+(X[0-9B]|[A-Z]{1,3})\s+([A-Z/]+)\s+([\d,]+\.\d{2})\s+([\d,]+\.\d{2})/);
        if (!m) return;
        const prev = lines[i - 1];
        rows.push({
          date: isoOf(m[1]),
          sec: secOf(m[2]),
          code: m[3],
          channel: m[4],
          amount: numOf(m[5]),
          balance: numOf(m[6]),
          desc: prev && !/^\d{1,2}\/\d{1,2}\//.test(prev.text) ? prev.text : "",
          raw: (prev && !/^\d{1,2}\/\d{1,2}\//.test(prev.text) ? prev.text + " | " : "") + t,
        });
      });
    });
    return rows;
  }

  /* ---------------- KBANK ----------------
     19-07-26 | 00:00 | รับโอนเงิน | 100.00 | 1,035.25 | K PLUS | จาก ...       */
  function parseKbank(pages) {
    const rows = [];
    pages.forEach((lines) => {
      lines.forEach((l) => {
        const t = l.text;
        if (!/^\d{2}-\d{2}-\d{2}\b/.test(t)) return;
        if (/ยอดยกมา|ยอดยกไป/.test(t)) return;
        const time = (t.match(/\b(\d{1,2}:\d{2})\b/) || [])[1];
        if (!time) return;
        const amts = l.items.filter((i) => AMT.test(i.s.trim()));
        if (amts.length < 2) return;
        const amount = numOf(amts[amts.length - 2].s);
        const balance = numOf(amts[amts.length - 1].s);
        const kind = (t.match(/(รับโอนเงิน|โอนเงิน|ฝากเงิน|ถอนเงิน|หักบัญชี|ดอกเบี้ย|ค่าธรรมเนียม)/) || [])[1] || "";
        const chIdx = l.items.findIndex((i) => i === amts[amts.length - 1]);
        const tail = l.items.slice(chIdx + 1).map((i) => i.s).join(" ").trim();
        rows.push({
          date: isoOf(t.slice(0, 8)),
          sec: secOf(time),
          code: kind,
          channel: tail.split(" จาก ")[0].split(" ไป ")[0].trim(),
          amount,
          balance,
          desc: tail,
          raw: t,
        });
      });
    });
    return rows;
  }

  /* ---------------- TrueMoney Wallet (TMN) ----------------
     03/06/2026 13:50:45 | เงินเข้า | 10.00 | 0952178672 | 34,210.07 | 34,220.07
     03/06/2026 13:50:46 | เงินออก | -0.29 | fee_p2p_receive | 34,220.07 | 34,219.78
     คอลัมน์: วันที่+เวลา · ประเภท · ยอด(±) · รายละเอียด(เบอร์/โค้ด) · ยอดก่อน · ยอดหลัง   */
  const TMN_FEE = /^(fee_|.*_fee$|promptpay_.*_fundout$|.*_fundout$)/i;
  function parseTMN(pages) {
    const rows = [];
    const re = /^(\d{2}\/\d{2}\/\d{4})\s+(\d{2}:\d{2}:\d{2})\s+(เงินเข้า|เงินออก)\s+(-?[\d,]+\.\d{2})\s+(.+?)\s+([\d,]+\.\d{2})\s+([\d,]+\.\d{2})\s*$/;
    pages.forEach((lines) => {
      lines.forEach((l) => {
        const m = l.text.match(re);
        if (!m) return;
        const detail = m[5].trim();
        rows.push({
          date: isoOf(m[1]),
          sec: secOf(m[2]),
          code: m[3], // เงินเข้า/เงินออก
          channel: "TMN",
          amount: Math.abs(numOf(m[4])),
          balance: numOf(m[7]),
          desc: detail,
          isFee: TMN_FEE.test(detail), // ค่าธรรมเนียม/โยกเงินออกธนาคาร ไม่ใช่รายการลูกค้า
          raw: l.text,
        });
      });
    });
    return rows;
  }

  /* ---------------- BAY (กรุงศรีอยุธยา) ----------------
     19/06/2026 22:28:12 | โอนเงิน | 144.00 | 1,278.86 | MOBILE | SCB PIMPORN KAEWS
       (บรรทัดถัดไป "บัญชีปลายทาง : X..." เป็นรายละเอียดต่อ)
     คอลัมน์ ถอน/ฝาก รวมเป็นช่องเดียว -> ทิศทางคำนวณจากผลต่างยอดคงเหลือใน applyDirection */
  function parseBAY(pages) {
    const rows = [];
    /* description ใช้ greedy (.+) เพื่อให้ยอด+ยอดคงเหลือผูกกับ "สองเลขสุดท้ายก่อน channel" เสมอ
       กันกรณีมีเลขทศนิยมในรายละเอียดมาแย่งคอลัมน์ยอด · ทศนิยมเป็น optional เผื่อยอดจำนวนเต็ม */
    const re = /^(\d{2}\/\d{2}\/\d{4})\s+(\d{2}:\d{2}:\d{2})\s+(.+)\s+([\d,]+(?:\.\d{2})?)\s+([\d,]+(?:\.\d{2})?)\s+([A-Za-zก-๙/]+)\s*(.*)$/;
    pages.forEach((lines) => {
      lines.forEach((l, i) => {
        const m = l.text.match(re);
        if (!m) return;
        if (/ยอดยกมา|ยอดยกไป|ยอดคงเหลือ/.test(m[3])) return;
        const next = lines[i + 1];
        const extra = next && /^บัญชีปลายทาง/.test(next.text) ? " " + next.text.trim() : "";
        rows.push({
          date: isoOf(m[1]),
          sec: secOf(m[2]),
          code: m[3].trim(), // โอนเงิน/รับโอน/ฝากเงิน ฯลฯ
          channel: m[6],
          amount: numOf(m[4]),
          balance: numOf(m[5]),
          desc: (m[7] || "").trim() + extra,
          raw: l.text,
        });
      });
    });
    return rows;
  }

  /* ---------------- ทั่วไป (สำรอง) ---------------- */
  function parseGeneric(pages) {
    const rows = [];
    pages.forEach((lines) =>
      lines.forEach((l) => {
        const t = l.text;
        const d = t.match(/(\d{1,2}[-/]\d{1,2}[-/]\d{2,4})/);
        const tm = t.match(/\b(\d{1,2}:\d{2})\b/);
        const amts = l.items.filter((i) => AMT.test(i.s.trim()));
        if (!d || !tm || amts.length < 2) return;
        rows.push({
          date: isoOf(d[1]),
          sec: secOf(tm[1]),
          code: "",
          channel: "",
          amount: numOf(amts[amts.length - 2].s),
          balance: numOf(amts[amts.length - 1].s),
          desc: t,
          raw: t,
        });
      }),
    );
    return rows;
  }

  /* ---------------- ทิศทาง: ใช้ผลต่างยอดคงเหลือเป็นหลัก ---------------- */
  function applyDirection(rows, bank) {
    let prevBal = null;
    rows.forEach((r, i) => {
      let dir = null;
      if (prevBal !== null && r.balance !== null && Math.abs(Math.abs(r.balance - prevBal) - r.amount) < 0.01) {
        dir = r.balance > prevBal ? "deposit" : "withdraw";
      }
      if (!dir) {
        const c = String(r.code || "").toUpperCase();
        if (bank === "SCB") {
          if (c === "X1") dir = "deposit";
          else if (c === "X2") dir = "withdraw";
          else if (c === "XB") dir = "adjustment";
        }
        if (!dir) {
          if (/รับโอน|ฝากเงิน|เงินเข้า|TRF FR|deposit/i.test(r.code + " " + r.desc)) dir = "deposit";
          else if (/โอนเงิน|โอนไป|ถอน|เงินออก|หักบัญชี|ค่าธรรมเนียม|TRF TO|withdraw/i.test(r.code + " " + r.desc)) dir = "withdraw";
        }
      }
      r.direction = dir || "deposit";
      if (r.balance !== null) prevBal = r.balance;
      r.seq = i;
    });
    return rows;
  }

  /* ---------------- KTB (กรุงไทย) ----------------
     วันที่กับเวลาอยู่คนละบรรทัด (เวลา HH:MM อยู่บรรทัดถัดไป) ปีเป็น พ.ศ. ย่อ (69 = 2569 = 2026)
       29/06/69 | เงินโอนเข้า (IORSDT) | 014-6444474223 | 30.00 | 16,492.01 | 606
       22:55
     บรรทัดสรุปท้าย ("รายการถอนทั้งหมด ...") ไม่ขึ้นต้นด้วยวันที่ จึงถูกข้ามอัตโนมัติ           */
  function parseKtb(pages) {
    const rows = [];
    pages.forEach((lines) => {
      lines.forEach((l, i) => {
        const t = l.text;
        if (!/^\d{1,2}\/\d{1,2}\/\d{2,4}\b/.test(t)) return;              // ต้องขึ้นต้นด้วยวันที่
        const amts = l.items.filter((it) => AMT.test(it.s.trim()));
        if (amts.length < 2) return;                                       // ต้องมี ยอด + คงเหลือ
        // เวลา: ในบรรทัดนี้ก่อน ไม่มีค่อยดูบรรทัดถัดไป (ที่ไม่ใช่แถวใหม่)
        let time = (t.match(/\b(\d{1,2}:\d{2})\b/) || [])[1];
        if (!time) {
          const nx = lines[i + 1];
          if (nx && !/^\d{1,2}\/\d{1,2}\/\d{2,4}\b/.test(nx.text)) time = (nx.text.match(/\b(\d{1,2}:\d{2})\b/) || [])[1];
        }
        const kind = (t.match(/(เงินโอนเข้า|โอนเงินออก|รับโอนเงิน|โอนเงิน|ฝากเงิน|ถอนเงิน|หักบัญชี|ดอกเบี้ย|ค่าธรรมเนียม)/) || [])[1] || "";
        const secVal = secOf(time); // KTB บางบัญชีไม่แสดงเวลา -> ถอยไปโหมด noTime เหมือน BBL (จับคู่ด้วยบัญชี+ยอด+ทิศทาง)
        rows.push({
          date: isoOf(t),
          sec: secVal === null ? 0 : secVal,
          noTime: secVal === null,
          code: kind,
          channel: "",
          amount: numOf(amts[amts.length - 2].s),
          balance: numOf(amts[amts.length - 1].s),
          desc: t.replace(/^\d{1,2}\/\d{1,2}\/\d{2,4}\s*/, "").trim(),
          raw: t + (time ? " " + time : ""),
        });
      });
    });
    return rows;
  }

  /* ---------------- BBL (กรุงเทพ) ----------------
     ไม่มีคอลัมน์เวลา — ตั้ง noTime แล้วให้ engine จับคู่ด้วยบัญชี+ยอด+ทิศทางภายในวัน
       10/06/26 | TRF FR OTH BK | 14.00 | 1,313.58 | mPhone     (FR = เงินเข้า, TO = เงินออก) */
  function parseBbl(pages) {
    const rows = [];
    pages.forEach((lines) => {
      lines.forEach((l) => {
        const t = l.text;
        if (!/^\d{1,2}\/\d{1,2}\/\d{2,4}\b/.test(t)) return;
        const firstAmtIdx = l.items.findIndex((it) => AMT.test(it.s.trim()));
        const amts = l.items.filter((it) => AMT.test(it.s.trim()));
        if (firstAmtIdx < 1 || amts.length < 2) return;                    // ต้องมี ถอน/ฝาก + คงเหลือ
        const particulars = l.items.slice(1, firstAmtIdx).map((it) => it.s).join(" ").trim();
        const via = (l.items[l.items.length - 1] || {}).s || "";
        rows.push({
          date: isoOf(t),
          sec: 0,
          noTime: true,                                                    // ไม่มีเวลาในสเตทเมนต์
          code: particulars,
          channel: "",
          amount: numOf(amts[amts.length - 2].s),
          balance: numOf(amts[amts.length - 1].s),
          desc: (particulars + " " + via).trim(),
          raw: t,
        });
      });
    });
    return rows;
  }

  /* ---------------- public ---------------- */
  async function parse(fileName, pages, businessDate) {
    const head = header(pages);
    let rows =
      head.bank === "SCB" ? parseScb(pages) : (head.bank === "KBANK" || head.bank === "LBK") ? parseKbank(pages) : head.bank === "KTB" ? parseKtb(pages) : head.bank === "BBL" ? parseBbl(pages) : head.bank === "TMN" ? parseTMN(pages) : head.bank === "BAY" ? parseBAY(pages) : parseGeneric(pages);
    if (!rows.length) rows = parseGeneric(pages);
    applyDirection(rows, head.bank);

    // ทีมใช้งานตั้งรอบจากวันที่ในหัวข้ออีเมล แต่ statement ธนาคารบางฉบับ
    // (โดยเฉพาะ KBANK) เป็นรายการของวันก่อนหน้า 1 วันทั้งฉบับ เมื่อทุกแถว
    // เป็นวันก่อนหน้ารอบเดียวกัน ให้ถือเป็น reporting lag ปกติและนำมาชนในรอบ
    // ที่ทีมระบุ โดยเก็บวันที่ต้นฉบับไว้ที่ sourceDate เพื่อสอบทานย้อนหลังได้
    const expectedPreviousDate = businessDate
      ? new Date(Date.parse(businessDate + "T00:00:00Z") - 86400000).toISOString().slice(0, 10)
      : null;
    const observedDates = new Set(rows.map((r) => r.date).filter(Boolean));
    const previousDayReport = !!(
      businessDate && expectedPreviousDate && observedDates.size === 1 && observedDates.has(expectedPreviousDate)
    );

    const company = typeof Formats !== "undefined" ? Formats.companyOf(fileName) : null;
    const dropped = {};
    const drop = (w) => (dropped[w] = (dropped[w] || 0) + 1);
    const records = [];
    rows.forEach((r, i) => {
      if (r.sec === null || r.amount === null) return drop("อ่านเวลาหรือยอดไม่ได้");
      if (r.direction === "adjustment") return drop("รายการปรับปรุงยอด (XB) แยกออกจากการจับคู่");
      if (r.isFee) return drop("ค่าธรรมเนียม/โยกเงินออกธนาคาร TrueMoney (ไม่ใช่รายการลูกค้า)");
      if (businessDate && r.date && r.date !== businessDate && !previousDayReport) return drop("วันที่ไม่ตรงกับวันที่ตรวจ");
      records.push({
        rowNo: i + 1,
        source: "stm",
        formatCode: "stm_pdf",
        date: previousDayReport ? businessDate : r.date,
        sourceDate: r.date,
        reportLagDays: previousDayReport ? 1 : 0,
        sec: r.sec,
        amount: Math.round(r.amount * 100) / 100,
        balance: r.balance,
        direction: r.direction,
        account: head.account || "UNKNOWN",
        bank: head.bank || "",
        channel: head.bank === "LBK" ? "LBK" : (r.channel || head.bank || ""), // LBK: บังคับ channel = "LBK" ให้ตรง registry (parseKbank คืน channel รก ๆ จากคอลัมน์รายละเอียด)
        company,
        username: null,
        ref: null,
        desc: r.desc,
        code: r.code,
        crossDay: false,
        lateNight: r.sec >= 82800,
        minutePrecision: true, // statement ให้เวลาแค่ HH:MM
        noTime: !!r.noTime, // BBL ไม่มีคอลัมน์เวลา — engine ผ่อนกรอบเวลาเป็นทั้งวัน
        raw: r.raw,
      });
    });

    const warnings = [];
    if (previousDayReport) warnings.push(`Statement เป็นข้อมูลวันที่ ${expectedPreviousDate} และถูกนำเข้ารอบ ${businessDate} ตามวันที่รายงาน`);
    if (!head.bank) warnings.push("ระบุธนาคารจากหัวกระดาษไม่ได้ — ใช้ตัวอ่านแบบทั่วไป");
    if (!head.account) warnings.push("อ่านเลขบัญชีจากหัวกระดาษไม่ได้ — ต้องระบุเองในหน้าตั้งค่าบัญชี");
    if (!records.length) warnings.push("ไม่พบบรรทัดรายการใน PDF — อาจเป็นไฟล์สแกนภาพ ต้องขอไฟล์ที่เป็นข้อความ");

    return {
      fileName,
      header: head,
      format: {
        source: "stm",
        bank: head.bank,
        company,
        headerIdx: 0,
        map: {},
        realCode: "stm_pdf",
        realLabel: `Statement PDF ${head.bank || ""} ${head.account || ""}`.trim(),
        channels: {},
        holder: head.holder,
        period: head.period,
      },
      records,
      aux: [],
      dropped,
      warnings,
      pageCount: pages.length,
    };
  }

  return { parse, textLines, header, isoOf, parseBAY, parseKbank, parseKtb, parseBbl, parseGeneric, applyDirection };
})();

